{% load static %}
{% for article in articles %}
<div class="article-preview">
  <div class="article-meta">
    <a href="{% url 'profile' username=article.author.username %}">
      <img src="{% if article.author.image %}{{ article.author.image }}{% else %}{% static 'images/default-avatar.svg' %}{% endif %}" alt="{{ article.author.username }}">
    </a>
    <div class="info">
      <a href="{% url 'profile' username=article.author.username %}" class="author">{{ article.author.username }}</a>
      <span class="date">{{ article.created|date:"F j, Y" }}</span>
    </div>
    {% include "partials/favorite_button.html" %}
  </div>
  <a href="{% url 'article_detail' slug=article.slug %}" class="preview-link">
    <h1>{{ article.title }}</h1>
    <p>{{ article.summary }}</p>
    <span>Read more...</span>
    {% if article.tags.all %}
    <ul class="tag-list">
      {% for tag in article.tags.all %}
      <li class="tag-default tag-pill tag-outline">{{ tag.name }}</li>
      {% endfor %}
    </ul>
    {% endif %}
  </a>
</div>
{% empty %}
<div class="article-preview">
  {% if active_tab == 'following' %}
  <p class="empty-feed-message">Your feed is empty. Check out the <a href="/">Global Feed</a>!</p>
  {% else %}
  <p class="empty-feed-message">No articles are here... yet.</p>
  {% endif %}
</div>
{% endfor %}

{% if pages|length > 1 %}
<nav>
  <ul class="pagination">
    {% for p in pages %}
    <li class="page-item{% if p == page %} active{% endif %}">
      <button class="page-link"
         hx-get="{% if active_tag %}{% url 'tag' tag=active_tag %}{% else %}/{% endif %}?{% if active_tab == 'following' %}feed=following&{% endif %}page={{ p }}"
         hx-target="#feed-content" hx-push-url="true">
        {{ p }}
      </button>
    </li>
    {% endfor %}
  </ul>
</nav>
{% endif %}

def _build_feed(request, tag=None):
    """Shared logic for home and tag views."""
    feed = request.GET.get("feed")
    try:
        page = int(request.GET.get("page", 1))
    except (ValueError, TypeError):
        page = 1
    offset = (page - 1) * ARTICLES_PER_PAGE

    queryset = Article.objects.with_favorites(request.user)

    if feed == "following" and not request.user.is_authenticated:
        return redirect("login")
    if feed == "following" and request.user.is_authenticated:
        followed_authors = User.objects.filter(followers=request.user)
        queryset = queryset.filter(author__in=followed_authors)
        active_tab = "following"
    elif tag:
        queryset = queryset.filter(tags__name=tag)
        active_tab = "tag"
    else:
        active_tab = "global"

    queryset = queryset.select_related("author").prefetch_related("tags").order_by("-created")
    total = queryset.count()
    articles = list(queryset[offset : offset + ARTICLES_PER_PAGE])
    total_pages = (total + ARTICLES_PER_PAGE - 1) // ARTICLES_PER_PAGE
    pages = range(1, total_pages + 1)

    tags = cache.get_or_set("all_tags", Tag.objects.all, timeout=300)

    context = {
        "articles": articles,
        "tags": tags,
        "active_tab": active_tab,
        "active_tag": tag,
        "page": page,
        "pages": pages,
    }

    if is_htmx(request):
        return render(request, "partials/feed_content.html", context)
    return render(request, "articles/home.html", context)


def home_view(request):
    tag = request.GET.get("tag")
    return _build_feed(request, tag=tag)


def tag_view(request, tag):
    return _build_feed(request, tag=tag)


